// ---- Screens no user requirement governs -----------------------------------
// WRITTEN DOWN RATHER THAN NOTICED. Every other screen is filed under at least
// one requirement — derived from its words or declared on the requirement —
// and these two are not. Each is a decision somebody made, with the reason
// beside it, so `check:ui` can fail on a THIRD appearing without one.
//
// This question could not be asked at all while the grouping was derived from
// text alone: inverting a strict match reports every near-miss as a gap, and it
// did — 31 of 54 screens, including the Field Call Register. It can be asked of
// the FILED set, because that is about where requirements actually sit.
//
// Neither entry is a defect on its own. Both are questions for a person, which
// is the point of writing them where a person will read them.
export const MODULES_WITHOUT_REQUIREMENT: Record<string, string> = {
  '/objective': 'The quality objectives are a QMS obligation (ISO 13485 §5.4.1) '
    + 'rather than something a user asked this system for. The servicing reference '
    + 'governs them; no URS claims to, and writing one to fill the gap would be '
    + 'inventing a requirement to satisfy a report.',
  '/settings': 'Per-device preferences — the CallReg endpoint, the theme. Nothing '
    + 'about the quality record depends on them, which is why no requirement '
    + 'reaches this screen.',
};

// ---- User Requirements -----------------------------------------------------
export type Risk = 'High' | 'Medium' | 'Low';
export interface Req {
  id: string; title: string; text: string; risk: Risk; refs?: string[];
  /** THE SCREENS THIS GOVERNS, WHERE ITS OWN WORDS DO NOT NAME THEM.
   *
   *  The grouping in `docs/REQUIREMENTS.md` is DERIVED by default: a
   *  requirement is filed under a module when its text names that module — its
   *  route, or every distinctive word of its label. That keeps the grouping
   *  evidence rather than opinion, and makes it move when the text does.
   *
   *  Derivation alone left 34 of 56 screens with no requirement section and the
   *  FIELD CALL REGISTER among them, which URS-003 plainly governs — it says
   *  "register a customer call" and never says "field". The user asked why
   *  registering a field call was not called out loud in the requirements; it
   *  was, and the document filed it under "not tied to one screen".
   *
   *  So: DERIVED BY DEFAULT, DECLARED BY EXCEPTION, and the document says which
   *  of the two put each requirement where it is. A declaration is a
   *  deliberate, auditable statement about one requirement — not a guess
   *  applied to 146 of them. Declaring modules does not switch derivation off:
   *  the two are UNIONED, so a requirement that later gains the words keeps
   *  being filed by them.
   *
   *  Every path must be a real module route; `check:ui` fails on one that is
   *  not, because a declaration pointing at a screen that does not exist files
   *  the requirement nowhere while looking as though it files it somewhere. */
  modules?: string[];
}
export const URS: Req[] = [
  { id: 'URS-076', title: 'A date is a date, whoever is reading it', risk: 'Medium',
    text: 'The system shall present every date in one written form. The system shall store every date as a date rather than as the text of one. A form that renders a date in the reader\u2019s own locale presents one record two ways to two people in one office, and a form that stores what was typed puts text in a date column \u2014 which nothing detects until the value is sorted, filtered or subtracted.',
    modules: ['/warranties', '/contracts'],
    refs: ['ISO 13485 \u00a74.2.4', 'ISO 13485 \u00a74.2.5'] },
  { id: 'URS-075', title: 'A request may be corrected until it has been answered', risk: 'Medium',
    text: 'The system shall allow a request for service to be corrected while it is awaiting a decision. The system shall prevent alteration of what a request asked for once a call has been raised from it. A request corrected after the call exists leaves two records of one event disagreeing about the customer, the machine or the fault, and the call is the record every count, report and review reads.',
    modules: ['/request-registration'],
    refs: ['ISO 13485 \u00a74.2.4', 'ISO 13485 \u00a77.5.4'] },
  { id: 'URS-074', title: 'A decision to supply rests on evidence that is retained', risk: 'Medium',
    text: 'The system shall record, for each customer, whether that customer has been verified. The system shall retain the records on which that verification rests. The system shall show both wherever the decision to supply is taken. A verification with no record behind it is an assertion, and the person relying on it downstream cannot check it.',
    modules: ['/parties', '/workload'],
    refs: ['ISO 13485 \u00a74.2.4', 'ISO 13485 \u00a77.2.2'] },
  { id: 'URS-073', title: 'Work that follows from a sale is raised from the sale', risk: 'Medium',
    text: 'The system shall raise the installation work for a sold machine from the record of its sale. The system shall carry the customer and the machine from that record to the work raised. Re-keying the customer, the model or the serial into a second form is where the two records stop describing the same machine, and nothing afterwards can tell which of them is right.',
    modules: ['/warranties'],
    refs: ['ISO 13485 \u00a77.5.1', 'ISO 13485 \u00a77.5.4'] },
  { id: 'URS-072', title: 'The terms of a parent record reach every record under it', risk: 'Medium',
    text: 'The system shall apply the terms recorded on a parent record to every record under it that states no term of its own. The system shall allow a record under a parent to state a term of its own. The system shall provide a means of returning every record under a parent to the parent\u2019s terms. The system shall state what such a return will discard before it discards it. A bulk load that copies a parent\u2019s values onto every child leaves every child stating terms of its own, so the parent moves nothing and nobody can see why.',
    modules: ['/warranties', '/contracts'],
    refs: ['ISO 13485 \u00a74.2.4', 'ISO 13485 \u00a77.5.4'] },
  { id: 'URS-071', title: 'Two records of one visit shall not contradict each other', risk: 'Medium',
    text: 'Where the system holds a customer\u2019s feedback about a visit, it shall also hold a completed service report for that visit, and every instance where it does not shall be visible as a list naming which record is absent. Feedback is collected after a visit has taken place, so its existence is evidence that the work occurred; the completed report is the record of what was done. The two disagreeing means a device was serviced and the servicing was never written up \u2014 a gap that is invisible from either record read on its own, because neither record is wrong in itself.',
    // DECLARED, with its reason. The requirement is about a RELATION between
    // two records, so its words name neither screen -- it is not "about" the
    // feedback register and not "about" the visit register. `/exports/feedback`
    // is where the feedback is read; `/feedback-without-report` is the list of
    // the ones with nothing behind them, which is this requirement read from
    // the other end. The same shape as URS-065 and `/missing-visit-reports`.
    modules: ['/exports/feedback', '/feedback-without-report'],
    refs: ['ISO 13485 \u00a74.2.4', 'ISO 13485 \u00a77.5.4', 'ISO 13485 \u00a78.2.1'] },
  { id: 'URS-065', title: 'A recovered quality record is reviewed before it is written', risk: 'High',
    text: 'Where records of work already done are recovered from a superseded system, each shall be resolved to the record it belongs to AND SHOWN TO AN OPERATOR BEFORE ANY OF IT IS WRITTEN, and only rows that resolved cleanly shall be written. A visit attached to the wrong call, or carrying another machine’s photograph, is a worse outcome than a visit still missing: the first is a false record of what was done to a device, the second is a gap that is visible as a gap. Rows that did not resolve shall be reported with the reason and left unwritten rather than written with a guess.',
    // DECLARED, with its reason. This requirement's own last clause is what
    // the screen is for -- "a gap that is visible as a gap" -- but its words
    // name no route, and it says "recovered", not "missing". `/reports` is
    // where a visit is loaded; `/missing-visit-reports` is the list of the
    // ones that are not there, which is the same requirement read from the
    // other end.
    modules: ['/reports', '/missing-visit-reports'],
    refs: ['ISO 13485 \u00a74.2.4', 'ISO 13485 \u00a77.5.4', 'MDR-2017 Fifth Schedule'] },
  { id: 'URS-066', title: 'A request awaiting registration is visible and is dispositioned', risk: 'Medium',
    // My Workload is where a request waiting on somebody becomes visible as
    // such.
    modules: ['/workload'],
    text: 'A request for service that has not yet become a call shall be visible as such, and shall reach one of a stated set of outcomes — registered as a new call, mapped to an existing call, or cancelled with a reason. It shall not be possible for a request to be silently dropped or to remain in no state at all, a request nobody can see being indistinguishable from a request nobody made.',
    refs: ['ISO 13485 \u00a77.5.4', 'ISO 13485 \u00a78.2.1'] },
  { id: 'URS-067', title: 'Authority over a quality record is held section by section', risk: 'High',
    // The sectional rights are granted in the matrix and tested on the call.
    modules: ['/roles', '/field-calls'],
    text: 'The authority to amend a call in progress shall be grantable SEPARATELY for each part of the record whose amendment means a different thing: the complaint as reported, the customer and device it names, the vigilance answers, and the customer’s contact details. Re-allocating a call to another engineer, and cancelling or restoring one, shall each be their own authority. A single \u201Cedit\u201D right cannot express the distinction the record requires — correcting a telephone number and re-answering whether a patient was harmed are not the same act — and each shall be attributable to the person who performed it.',
    refs: ['ISO 13485 \u00a74.2.4', 'ISO 13485 \u00a74.2.5', 'ISO 13485 \u00a78.2.2', 'MDR-2017 Fifth Schedule'] },
  // ---- Rev 2.4 (2026-09-13) ----------------------------------------------
  { id: 'URS-064', title: 'A credential cannot be recovered from a log', text: 'No log, error message or build record the system produces shall contain any part of a credential. Where a credential is malformed such that a subsystem would report a fragment of it, the operation shall be REFUSED before that subsystem is reached, and the refusal shall say what to correct without reproducing any part of the value. Masking the credential is not by itself sufficient: a subsystem reports the piece it failed on, which may be a fragment matching neither the credential nor the string containing it.', risk: 'High', refs: ['ISO 13485 \u00a74.1.6', 'ISO 13485 \u00a74.2.4', 'Information Technology Act, 2000', 'MDR-2017 Fifth Schedule'] },
  { id: 'URS-063', title: 'A read-only role holds no authority to write, and a derived role does not track its source', text: 'Where a role is described as read-only it shall hold no permission that any write policy names, so that a refusal is the database’s and not a hidden control. Where a role is created by COPYING another, the copy shall be a one-time act and the two shall not thereafter be kept in step, so that granting an authority on one role cannot confer it on another. A periodic report shall state the write authority each such role holds; it shall present that as a matter for review rather than as a defect, because a grant may be deliberate and no re-application of configuration can remove one.', risk: 'High',
    // Read-only is a claim the matrix makes, so the matrix is where it is
    // kept true.
    modules: ['/roles'], refs: ['ISO 13485 \u00a74.1.6', 'ISO 13485 \u00a76.2', 'MDR-2017 Fifth Schedule'] },
  { id: 'URS-062', title: 'A loaded register can be corrected by loading it again', text: 'Every register that may be populated from a file shall have a natural key drawn from the file itself, so that re-loading a corrected export UPDATES the records it names rather than adding them a second time. The key shall be one the data interface can infer, and its sufficiency shall be verified against a database rather than by inspection. A row not carrying the key shall be refused and the reason given, a row that cannot be matched on a re-run being one that arrives again on every load.', risk: 'Medium',
    // Re-loading a corrected export is what this screen is for.
    modules: ['/bulk-uploads'], refs: ['ISO 13485 \u00a74.2.4', 'ISO 13485 \u00a74.2.5', 'MDR-2017 Fifth Schedule'] },
  { id: 'URS-061', title: 'A value that cannot be determined is recorded as unknown', text: 'Where the system completes a value the record did not supply and the source cannot answer, the field shall be left EMPTY and the record retained. It shall not be filled with a value that is available but untrue, and the record shall not be discarded for want of it. What is known — that this happened, to this device, on this date, under this paperwork — is the record; the part that is unknown is one field.', risk: 'High', refs: ['ISO 13485 \u00a74.2.4', 'ISO 13485 \u00a74.2.5', 'ISO 13485 \u00a77.5.8', 'MDR-2017 Fifth Schedule'] },
  { id: 'URS-060', title: 'A record is keyed on what identifies it', text: 'The key of a quality or servicing record shall be the whole of what identifies it. Where a record concerns a DEVICE, the device is its model together with its serial number, serial numbers being repeated across models. Where one document concerns SEVERAL devices, each device shall hold its own record under that document’s number. A key narrower than the identity does not fail loudly — it silently replaces one record with another — so the sufficiency of such a key shall be established by MEASUREMENT against the data to be loaded, before that data is loaded.', risk: 'High',
    // A machine is its model AND its serial — which is what these two
    // registers are keyed on.
    modules: ['/product-database', '/product-master'], refs: ['ISO 13485 \u00a74.2.4', 'ISO 13485 \u00a74.2.5', 'ISO 13485 \u00a77.5.8', 'ISO 13485 \u00a78.2.6', 'MDR-2017 Fifth Schedule'] },
  // ---- Rev 2.1 (2026-09-11) ----------------------------------------------
  { id: 'URS-053', title: 'A service record identifies the individual device', text: 'Every service call shall identify the single machine it concerns by its serial number, from the request onward. A record that names a product but not a unit cannot be traced to the device serviced, and its cover, warranty and contract cannot be established.', risk: 'High',
    // The serial is what makes a call a record of one device, and what
    // Machine History reads it back by.
    modules: ['/field-calls', '/machine-history'], refs: ['ISO 13485 §7.5.8', 'ISO 13485 §7.5.9', 'ISO 13485 §7.5.4'] },
  { id: 'URS-054', title: 'Consumption recorded against a call is complete', text: 'Every part fitted during a visit shall be recorded against that call. Recording shall not depend on a further confirming action by the engineer once the part has been entered, and where no part was used that shall be a STATED answer rather than an unanswered field.', risk: 'High',
    // What was fitted, and the two reports that ask whether it was all
    // accounted for against the call.
    modules: ['/spare-consumption', '/exports/consumption', '/exports/unused'], refs: ['ISO 13485 §7.5.4', 'ISO 13485 §7.5.9'] },
  { id: 'URS-055', title: 'The report on a closed call is reviewed', text: 'A closed call’s service report shall be subject to review by a competent person other than routine daily coding of the failure, with the reviewer and the time recorded. The reviewer shall be able to return the call to open where the report does not close it, and to correct consumption where a part was fitted and not booked.', risk: 'Medium', refs: ['ISO 13485 §7.5.4', 'ISO 13485 §8.2.1', 'ISO 13485 §8.2.4'] },
  { id: 'URS-058', title: 'A judgement on a quality record names the person who made it', text: 'Where the system records a judgement about a product failure, it shall record WHO made that judgement, taken from the authenticated session at the moment the judgement is completed and not from a value supplied by the caller. The identity shall not be displaced by later editing of the same record, and where the judgement is carried onto a further record the person shall be carried with it. No record shall attribute a judgement to a screen, a process or the system itself.', risk: 'High',
    // The judgement is made in the review and carried into the failure
    // report.
    modules: ['/daily-review', '/failure-report'], refs: ['ISO 13485 \u00a74.2.5', 'ISO 13485 \u00a78.2.2', 'MDR-2017 Fifth Schedule'] },
  { id: 'URS-059', title: 'Every change to a field failure report is recorded', text: 'Each amendment to a field failure report shall be recorded with what changed — the previous and the new value of each field — together with who changed it and when. The record of amendments shall be produced by the system itself rather than by the application requesting it, shall not be alterable or removable through the application, and shall begin at the creation of the report.', risk: 'High',
    // The amendment log belongs to the register it logs.
    modules: ['/failure-report'], refs: ['ISO 13485 \u00a74.2.4', 'ISO 13485 \u00a74.2.5', 'ISO 13485 \u00a78.5.2', 'MDR-2017 Fifth Schedule'] },
  { id: 'URS-057', title: 'A person’s signature is applied by that person alone', text: 'A user shall be able to record their own handwritten signature and have it reproduced on the documents that name them as signatory. The recorded signature shall be readable and writable only by the person it belongs to — by no manager, and by no administrator — and shall be reproduced on a document only where the signature block names the person producing it; in every other case the block shall be produced blank for signature by hand. Removal of a signature belonging to a person who has left shall be an authorised act which does not disclose the signature.', risk: 'High', refs: ['ISO 13485 \u00a74.2.4', 'ISO 13485 \u00a74.2.5', 'Information Technology Act, 2000', 'MDR-2017 Fifth Schedule'] },
  { id: 'URS-056', title: 'An access role always has a defined permission set', text: 'A role by which access is granted shall never exist without an explicit set of permissions. Where a role is added by configuration it shall be derived from an existing role, so that no role can be brought into use whose effective authority is implied rather than stated.', risk: 'High',
    // A role without a permission set is created — or prevented — here.
    modules: ['/roles'], refs: ['ISO 13485 §4.1.6', 'ISO 13485 §6.2', 'MDR-2017 Fifth Schedule'] },
  { id: 'URS-001', title: 'Authenticated access', text: 'Only authenticated, authorised personnel shall access the system, each with a unique user identity.', risk: 'High' },
  { id: 'URS-002', title: 'Role-based visibility', text: 'A user shall see and act on only the records their role permits: an engineer their own calls, a manager their reporting team, office/administration roles as defined.', risk: 'High',
    // Visibility is configured in Roles & Permissions and granted in User
    // Access; the call registers are where it is felt.
    modules: ['/roles', '/users', '/field-calls'] },
  { id: 'URS-003', title: 'Register a service call', text: 'The service desk shall register a customer call capturing customer, product, serial, complaint and reported problem, and the system shall assign a unique call number (UCN).', risk: 'High',
    // Registering a call is what the Field Call Register IS, and the same act
    // on an installation, a PM and a request awaiting registration. The text
    // says "register a customer call" and never says "field", so no
    // derivation reaches the screen the user went looking for.
    modules: ['/field-calls', '/installations', '/pm-calls', '/pending-registrations'] },
  { id: 'URS-004', title: 'Record a visit / call report', text: 'An engineer shall record each visit with call status, observations, work done and readings; the call status shall reflect the latest visit.', risk: 'High',
    // A visit report IS this screen; the requirement calls it a "call
    // report".
    modules: ['/reports'] },
  { id: 'URS-005', title: 'Preventive maintenance', text: 'The company shall schedule and record preventive-maintenance (PM) visits, including bulk creation of the monthly PM batch by an administrator.', risk: 'Medium' },
  { id: 'URS-006', title: 'Installation control', text: 'Creation of installation calls shall be restricted to the Commercial function; installation records shall capture the warranty start date.', risk: 'Medium' },
  { id: 'URS-007', title: 'Spare request & approval', text: 'An engineer shall request spare parts against a call; the request shall follow a defined multi-stage approval chain, each stage authorised by the correct role.', risk: 'High' },
  { id: 'URS-008', title: 'Spare dispatch & receipt', text: 'Stores shall dispatch approved spares and the requesting engineer shall acknowledge receipt; each step shall be recorded with actor and time.', risk: 'Medium',
    // Dispatch is Stock Out; the acknowledgement is Pending Dispatch.
    modules: ['/spare-dispatch', '/stock-out'] },
  { id: 'URS-009', title: 'Stock accuracy', text: 'Hand stock, stock transfers and material returns shall be tracked so an engineer cannot transfer or return more than they hold.', risk: 'Medium' },
  { id: 'URS-010', title: 'Master data', text: 'Party, product, part and user master data, and configurable value lists, shall be maintained under control.', risk: 'Medium',
    // The masters overview and the two product registers are master data; the
    // text names the parties, parts and users but not the screens that hold
    // them.
    modules: ['/masters', '/product-database', '/product-master'] },
  { id: 'URS-011', title: 'Warranty & contract cover', text: 'Warranty and contract cover per machine shall be maintained and reflected on calls.', risk: 'Medium',
    // Cover per machine is maintained on these two registers, and a transfer
    // carries it to the machine’s new owner.
    modules: ['/warranties', '/contracts', '/ownership-transfer'] },
  { id: 'URS-012', title: 'Customer feedback', text: 'Customer feedback captured on a call shall be recorded and retrievable per question.', risk: 'Low' },
  { id: 'URS-013', title: 'Reports & analytics', text: 'Authorised users shall retrieve visit history and analytics; export shall be permitted only to authorised roles.', risk: 'Medium',
    // Each export is one of the analytics this requirement governs; it names
    // the parent screen only.
    modules: ['/exports/consumption', '/exports/kpi', '/exports/unused', '/exports/calls', '/exports/feedback'] },
  { id: 'URS-014', title: 'SLA monitoring', text: 'The company shall define service-level targets and the system shall highlight open calls that are due or breached.', risk: 'Medium',
    // The targets are defined in Admin Config and the breach is shown on the
    // Dashboard and in Pending Calls.
    modules: ['/', '/pending-calls', '/admin-config'] },
  { id: 'URS-015', title: 'Notifications', text: 'An engineer shall be notified in-app when a call is allotted to them or a requested spare is dispatched.', risk: 'Low' },
  { id: 'URS-016', title: 'Audit trail', text: 'The system shall keep a secure, attributable, time-stamped audit trail of key actions that users cannot alter.', risk: 'High', refs: ['ISO 13485 §4.2.5'] },
  { id: 'URS-017', title: 'Data integrity & retention', text: 'Records shall be complete, accurate and retained and retrievable for the required retention period (ALCOA+).', risk: 'High', refs: ['ISO 13485 §4.2.5', 'MDR-2017 Fifth Schedule'] },
  { id: 'URS-018', title: 'Availability & recovery', text: 'The system and its records shall be backed up and recoverable.', risk: 'Medium' },
  { id: 'URS-019', title: 'Controlled change', text: 'Changes to the software shall be version-controlled, tested and approved; each release shall be uniquely identifiable in-app.', risk: 'Medium',
    // The release is identified in Version History, the change is validated
    // in the package, and the work itself is tracked.
    modules: ['/version-history', '/software-validation', '/tracker'] },
  { id: 'URS-020', title: 'Knowledge base', text: 'The team shall maintain how-to guidance and field-solution knowledge within the system.', risk: 'Low',
    // The manuals and the field-solution notes are kept here, and "How RITHI
    // Functions" is the same requirement met a third way — guidance maintained
    // WITHIN the system rather than in a document somebody has to be sent.
    // (The other two Knowledge Base entries are open to everyone and are not
    // modules, so there is nothing to file under them.)
    modules: ['/service-manuals', '/knowledge-base/how-it-works'] },
  { id: 'URS-021', title: 'Partial issue of spares', text: 'Stores shall be able to issue fewer units of a spare than were requested when only part of the quantity is available, and the outstanding balance shall remain visible as still due.', risk: 'Medium',
    // Issuing fewer than were asked for is done here, and the balance stays
    // open.
    modules: ['/stock-out'] },
  { id: 'URS-022', title: 'Acknowledged receipt', text: 'The engineer shall confirm each delivery of a spare as it is received, and a spare shall be recorded as received only when the whole quantity has been confirmed.', risk: 'Medium',
    // The engineer acknowledges each delivery from this screen.
    modules: ['/spare-dispatch'] },
  { id: 'URS-023', title: 'Reconciliation of consumption', text: 'Authorised office roles shall be able to record a spare consumed against a call that the engineer did not report, correct a quantity reported in error, and void an entry made in error, with a reason retained for each.', risk: 'High' },
  { id: 'URS-024', title: 'Stock integrity', text: 'No spare shall be recorded as consumed in excess of the quantity the engineer holds, so that hand-stock balances cannot become negative.', risk: 'High' },
  { id: 'URS-025', title: 'Re-opening a closed call', text: 'A closed call shall be re-openable by an authorised role where further work or correction is required, and the re-opening shall be recorded.', risk: 'Medium',
    // Re-opening is done from the call, and read from the review.
    modules: ['/field-calls', '/call-review'] },
  { id: 'URS-027', title: 'Refurbished spares', text: 'Where a recycled spare is issued in place of a new one, it shall be identified by its own part number, held and consumed as that part, and the engineer shall be told the part is refurbished. Only a part held in Part Master and active may be issued this way.', risk: 'High' },
  { id: 'URS-028', title: 'Dispatch performance', text: 'The time taken by Stores to issue an approved spare shall be measurable, from the moment the spare cleared its last approval to the moment it was issued.', risk: 'Low' },
  { id: 'URS-029', title: 'Service manuals available at the point of work', text: 'The service documentation for a product shall be held centrally and presented to the engineer on the call for that product, so the machine is worked on against its own manual rather than one found by memory or by hunting a shared folder.', risk: 'Medium' },
  { id: 'URS-030', title: 'Controlled QMS documents', text: 'Quality-system documents (SOPs, work instructions, forms) shall be held with their document number, revision and effective date, be readable by every user, and be maintainable only by the role responsible for the quality system. A superseded document shall be withdrawn from use without being destroyed.', risk: 'High' },
  { id: 'URS-031', title: 'Find a machine, or a customer’s machines', text: 'A user shall be able to identify the customer holding a given product and serial number, and to list every machine and serial number recorded against a given customer, without needing to know how either is spelled in the register.', risk: 'Low',
    // Finding the machine, the register it is found in, and what happened to
    // it.
    modules: ['/lookup', '/product-database', '/machine-history'] },
  { id: 'URS-032', title: 'Allotment and re-allotment of calls', text: 'A reporting manager shall be able to allot a call to, or move a call between, the engineers reporting to them and themselves, including several calls in one action, changing nothing on the call but the engineer it is allotted to.', risk: 'High',
    // Allotment happens on the register, and Pending Calls is where an
    // unallotted one is found.
    modules: ['/field-calls', '/pending-calls'] },
  { id: 'URS-033', title: 'Grouping a register', text: 'A user shall be able to group a register by the values of a column — and by more than one column at a time — so a manager can read a list by region, then by engineer, then by call status, without exporting it.', risk: 'Low' },
  { id: 'URS-034', title: 'Requesting on behalf of an engineer', text: 'A reporting manager shall be able to raise a spare request, a call registration request or a visit report for an engineer reporting to them, with the record attributed to that engineer and the manager’s identity retained as its author.', risk: 'Medium' },
  { id: 'URS-035', title: 'Correcting who a spare order is for', text: 'An administrator shall be able to correct the engineer a spare order was raised against while it is still awaiting issue, and shall be prevented from doing so once any part of it has been issued. Every such change shall be retained with both names, the person who made it, the time and the reason.', risk: 'High',
    // Correcting who the order is for is done on the request, before it is
    // issued.
    modules: ['/spare-requests'] },
  { id: 'URS-036', title: 'Reliability and consumption analysis', text: 'Authorised users shall be able to read how often each product fails RELATIVE TO THE NUMBER IN THE FIELD, how it fails, and what spare parts are consumed under each type of cover and in each region, computed from the service record rather than maintained separately.', risk: 'Medium',
    // The two screens that answer "how does it fail, and what does fixing it
    // consume" — this requirement is what they were built for.
    modules: ['/product-failure', '/spare-insights'] },
  { id: 'URS-037', title: 'Migrated data is distinguishable from the system’s own record', text: 'Where a stock or service figure is derived partly from records MIGRATED from the superseded system and partly from records this system created, a user shall be able to see how much of the figure comes from each, and to read the figure without the migrated part. Neither reading shall be presented as a correction of the other.', risk: 'High', refs: ['ALCOA+ (Attributable, Original)'] },
  { id: 'URS-038', title: 'Closing a stock period', text: 'An authorised role shall be able to close a stock period, fixing an opening figure per engineer and part that stands for every movement up to that date, so the register need not re-derive settled history. A close shall not change any balance.', risk: 'High' },
  { id: 'URS-039', title: 'Identifier continuity across a migration', text: 'Record identifiers shall remain unique and continue in sequence after historical records carrying their own identifiers are loaded; the system shall not re-issue an identifier the migrated data already uses.', risk: 'High',
    // A migration arrives through the importer, and its identifiers must not
    // collide with the system’s own.
    modules: ['/bulk-uploads'] },
  { id: 'URS-040', title: 'A bulk load shall not silently alter what it does not carry', text: 'Loading a file shall change only the fields that file supplies. A value the file leaves empty shall take the value the system defines for it, and shall not be written as empty or null; a load that cannot honour this shall fail rather than write.', risk: 'High',
    // Every screen that loads a file, since this is a rule about what a file
    // does NOT carry.
    modules: ['/bulk-uploads', '/pm-bulk-upload', '/report-mapping'] },
  { id: 'URS-041', title: 'Migrated stock belongs to a person who can hold it', text: 'A stock balance shall be opened only against an active member of the user directory; identifiers appearing in a migrated file that are not people (dealers, customers) shall be excluded before loading, and what is excluded shall be reported.', risk: 'Medium' },
  { id: 'URS-042', title: 'Response within a working time', text: 'A register shall return within a time that allows the work it supports, on the full production data volume and with access rules in force.', risk: 'Medium' },
  { id: 'URS-043', title: 'Decision support', text: 'The system may SUGGEST a controlled value to the person entering it, provided the suggestion is drawn from the record, states its grounds, can be overruled, and is never written without a person choosing it. What was offered and what was accepted shall be retained so the suggestion quality can be reviewed.', risk: 'Medium' },
  { id: 'URS-044', title: 'Attributable registration', text: 'A registered call shall record BOTH the Hotline desk it belongs to and the individual who registered it. Only the Hotline engineer is trained on the vigilance questions answered at registration, so a call registered by anyone else shall be identifiable from the record without reconstruction. The individual shall be taken from the authenticated session and shall not be settable by the application or by a client of the API.', risk: 'High',
    // Both registrant columns are stamped where a call is typed in.
    modules: ['/field-calls', '/pending-registrations'] },
  { id: 'URS-045', title: 'Controlled vocabulary is chosen, not typed', text: 'Where a field must match a controlled list — a Standard Complaint above all — the value shall be CHOSEN from that list and shall not be typed freehand, and no keystroke shall commit a value on its own. Counting, filtering, repeat-failure detection and every downstream report match on the stored value, so a hand-entered variant is a record that no analysis will ever find. Where a list is empty the field shall say so rather than accept arbitrary text.', risk: 'High' },
  { id: 'URS-046', title: 'Repeat failure determined to the documented rule', text: 'The review shall determine whether a call is a repeat failure by the rule the servicing procedure states — counting the call under review, within the stated window, on the same equipment or the same part in the same machine — and shall present the rule alongside the verdict so a judgement recorded under one rule is not mistaken for one recorded under another. Window and threshold shall be maintainable by an administrator without a code change. Where the machine cannot be identified the review shall say so rather than report no repeat failure.', risk: 'High' },
  { id: 'URS-047', title: 'Spares sent to a call are accounted for against it', text: 'A spare that reached an engineer for a specific call shall be accounted for in that call’s consumption, and any shortfall shall be reportable — whether nothing was booked or less than was sent. A part refused or never dispatched shall not be reported as unaccounted for, because nothing arrived to be fitted. The determination shall be made only once the call is closed.', risk: 'Medium' },
  { id: 'URS-048', title: 'Cover continues across a contract renewal', text: 'A maintenance contract shall be renewable from its predecessor without the machine list being re-keyed, and the renewal shall carry a recorded link back to the contract it replaces. Cover shall be continuous: the successor begins the day after the predecessor ends, so no machine is momentarily uncovered and none is covered twice. Prices shall NOT be carried forward, a renewal being re-priced.', risk: 'Medium',
    // A renewal is raised from its predecessor on the Contract Register.
    modules: ['/contracts'] },
  { id: 'URS-049', title: 'Custody of equipment held on the organisation’s premises', text: 'Equipment taken into the organisation’s own premises shall be recorded on a register that identifies it, states WHOSE property it is, and holds the condition it arrived in — that condition being the baseline against which any later damage is judged. Where such equipment is lost, damaged or found unfit for use, that shall be recorded and reported to its owner. The register shall distinguish the organisation’s own stock from a customer’s property, because the duty of care applies to one and not the other, and shall not require a service call to exist: equipment may be held for reasons that have no call.', risk: 'High' },
  { id: 'URS-050', title: 'Decontamination before the equipment is worked on', text: 'Equipment returned from use shall be cleaned and disinfected to the applicable work instruction before it is worked on, and that shall be recorded with who did it, when, and against WHICH REVISION of the instruction. Where the work involves opening or dismantling the equipment, the record shall be a PRECONDITION of that work rather than a note made after it.', risk: 'High',
    // Decontamination is recorded when the equipment is received here.
    modules: ['/indoor'] },
  { id: 'URS-051', title: 'A quality check separable from the work it checks', text: 'Work performed on equipment before it is returned shall be subject to a recorded quality check held as its own record, attributable to the person who performed it. The authority to sign the check shall be grantable separately from the authority to do the work, so that the two may be different people. Equipment whose check has failed, and work of a kind that requires a check and has none, shall not leave.', risk: 'High',
    // The quality check before the equipment goes back is a step of this
    // register.
    modules: ['/indoor'] },
  { id: 'URS-052', title: 'Scrapping equipment is an authorised act', text: 'Condemning equipment shall require an authority granted for that purpose alone, shall record who condemned it and why, and shall be refused to anybody not holding that authority. Parts recovered from condemned equipment shall be recorded with their condition, and shall not enter usable stock in a way that makes them indistinguishable from new parts.', risk: 'High' },
  { id: 'URS-026', title: 'Preventive-maintenance scheduling', text: 'The monthly preventive-maintenance batch shall be created for a stated due month, retaining the date it was uploaded, and shall support loading earlier months.', risk: 'Medium' },
  { id: 'URS-068', title: 'One identified record per machine, assembled from every register that names it', text: 'Every machine the organisation has sold, contracted or recovered shall appear exactly once in a register of machines, identified by its MODEL together with its SERIAL \u2014 never by the serial alone, which repeats across models. That record shall be assembled from the warranty sale register, the contract register, the additional entries, the ownership transfer register and the installation call, and shall state for each of the party, the warranty and the contract WHICH register decided it, so the record can be checked against its evidence. Where the registers disagree, the most recently dated evidence shall decide.', risk: 'High',
    modules: ['/product-database-2', '/warranties', '/contracts', '/ownership-transfer'] },
  { id: 'URS-069', title: 'What a machine is covered by today is derived, not typed', text: 'Whether a machine is inside its warranty, under a maintenance contract, or covered by neither shall be DERIVED from the recorded warranty and contract periods rather than stored as an opinion that ages. A machine inside its warranty is under warranty (WGP) even where a contract also covers it; a labour contract is AMC and a comprehensive contract is CMC; a machine covered by neither is OGP. A contract whose type was never recorded shall be reported as such and shall never be assumed to be either kind.', risk: 'High',
    modules: ['/product-database-2'] },
  { id: 'URS-070', title: 'A warranty starts when the machine was installed', text: 'The warranty period of a machine shall start from the date recorded on its installation \u2014 the Warranty Start Date captured when the installation call is reported, or failing that the date that call was solved \u2014 and shall fall back to the selling register only where no installation was recorded. The end of the period shall be derived from that start and the recorded period, by the same arithmetic the rest of the application uses.', risk: 'High',
    modules: ['/product-database-2', '/installations'] },
];

// ---- System / Functional Requirements -------------------------------------
export interface FReq extends Req { urs: string[] }
export const FRS: FReq[] = [
  { id: 'FRS-090', urs: ['URS-072', 'URS-074'], risk: 'Medium', title: 'What the period suggests, and what the customer register holds',
    text: 'FRS-090.1 The cover registers shall calculate a PM visit count from the recorded period. FRS-090.2 The cover registers shall accept a PM visit count entered by the operator. FRS-090.3 The cover registers shall retain an entered PM visit count when the period or the start date is subsequently changed. FRS-090.4 The warranty register shall re-read the address, the contact details and the tax registrations of the named customer from the customer register when the operator requests it. FRS-090.5 The warranty register shall state each field that request would change, with its present and its proposed value, before changing any. FRS-090.6 The warranty register shall change no field where the customer register holds no such customer. RATIONALE: .1 and .3 together are the requirement \u2014 three visits a year is the standard OFFER and what was sold is on the purchase order, so a count that keeps reverting to the offer whenever a start date is corrected is a field somebody re-types until they give up, and one that never follows the period makes every ordinary sale a manual entry. The test for "has it been changed" is whether it still equals what the period suggested BEFORE the edit, which is the same rule a machine uses to pin a field away from its entry. .5 because the installation address on a sale legitimately differs from the registered one: a sale whose address changed silently under an operator who had corrected it by hand is worse than one that is visibly out of date, because the first is wrong and nobody knows. .6 because blanking a sale on the ground that the customer register has never heard of the customer would destroy the only address anybody has.' },
  { id: 'FRS-089', urs: ['URS-076'], risk: 'Medium', title: 'A date field reads dd-MMM-yyyy and stores a date',
    text: 'FRS-089.1 The cover registers shall display every date value in the form dd-MMM-yyyy. FRS-089.2 The cover registers shall present a date input control when a date field receives focus. FRS-089.3 The cover registers shall store the value produced by that control. FRS-089.4 The cover registers shall derive no date value from text entered by the operator. RATIONALE: a native date control renders in the BROWSER\u2019S locale and no attribute changes it \u2014 two machines in one office showed `2026-09-12` and `09/11/2026` for one field. The obvious alternative is the dangerous one: a text box holding `20-Apr-2026` saved as typed puts a formatted string in a date column, and nothing detects it until the value is sorted, filtered or subtracted. FRS-089.4 is therefore a prohibition rather than a convenience, and `check:ui` refuses a parser appearing in that component at all.' },
  { id: 'FRS-088', urs: ['URS-074'], risk: 'Low', title: 'The installations awaiting Commercial',
    text: 'FRS-088.1 My Workload shall list the number of installation requests for which no call has been raised. FRS-088.2 My Workload shall state, of those, the number whose customer is verified. FRS-088.3 My Workload shall state, of those, the number whose customer is not verified. FRS-088.4 My Workload shall state, of those, the number whose customer is absent from the customer register. FRS-088.5 My Workload shall open the request register filtered to the stated subset when the operator selects a count. FRS-088.6 The request register shall display the verification status of the customer named by each request. RATIONALE: FRS-088.4 is separate from FRS-088.3 because the two need opposite actions \u2014 a customer who is absent is added, a customer who is present is verified \u2014 and a figure that merges them sends somebody to verify a customer who does not exist. The section is offered to every operator who may open the request register rather than to one department, because a count over a list the reader may not open is both useless and a disclosure of its size.' },
  { id: 'FRS-087', urs: ['URS-075'], risk: 'Medium', title: 'Correcting a call request, and the freeze that ends it',
    text: 'FRS-087.1 The request register shall allow an operator holding call-creation rights, registration rights or authorship of the request to alter the customer, the machine, the fault, the engineer and the plan recorded on it. FRS-087.2 The request register shall refuse every such alteration to a request whose status is other than Pending. FRS-087.3 The database shall refuse every such alteration to a request whose status is other than Pending. FRS-087.4 The database shall name, in its refusal, each field it refused. FRS-087.5 The database shall permit alteration of the unique call number, the status, the actioning operator, the actioning time, the cancellation reason and the cancellation time in every status. FRS-087.6 The request register shall exclude the unique call number and the status from the fields an operator may alter. RATIONALE: FRS-087.3 repeats .2 in the DATABASE and is not redundant \u2014 `cr_update` lets the person who raised a request write their own row, so a control that lives only in the form is one a direct API call walks past. FRS-087.5 is what makes this a trigger rather than a policy: registering a request writes four of those columns and cancelling writes three, so a rule over the whole row would refuse the very actions that answer a request.' },
  { id: 'FRS-086', urs: ['URS-074'], risk: 'Medium', title: 'KYC records attached to a customer',
    text: 'FRS-086.1 The customer register shall attach a document to a customer and shall record its name, its location, the operator who attached it and the time. FRS-086.2 The customer register shall display the verification status of each customer in its list. FRS-086.3 The customer register shall display a link to each attached record in that list. FRS-086.4 The system shall treat a customer as verified on the recorded status alone. FRS-086.5 The system shall treat no customer as verified by the presence of an attached record. FRS-086.6 The customer register shall state, for a verified customer with no attached record, that the record is absent. FRS-086.7 The customer register shall retain a removed record in the document store. RATIONALE: .4 and .5 are the two halves of one asymmetry. The status is a DECISION a person made, and withholding it because the paperwork was filed elsewhere would make the system stricter than the people it serves; attaching a file is not a decision, so it can never make a customer verified. .7 because a KYC record somebody relied on is worth keeping wherever it sits.' },
  { id: 'FRS-085', urs: ['URS-073'], risk: 'Medium', title: 'Installation calls raised from a Sale Entry',
    text: 'FRS-085.1 The warranty register shall raise one installation call for each machine on a sale entry that has no installation call. FRS-085.2 Each such call shall carry the customer, the city and the state recorded on the sale entry. FRS-085.3 Each such call shall carry the model and the serial recorded on the machine. FRS-085.4 Each such call shall record the standard complaint and the reported complaint as "Installation Calls". FRS-085.5 Each such call shall record No against the public health threat, the death and the serious incident questions. FRS-085.6 Each such call shall record no customer contact. FRS-085.7 Each such call shall carry the warranty number, the warranty start and the warranty end of the sale entry where the sale entry records a warranty. FRS-085.8 Each such call shall record no cover where the sale entry records no warranty. FRS-085.9 The warranty register shall record the unique call number of each raised call against the machine it was raised for. FRS-085.10 The warranty register shall raise no call for a machine whose model or serial is absent. FRS-085.11 The warranty register shall stop, and shall name the machine, where a raised call cannot be recorded against it. RATIONALE: .5 states the honest answer for a machine that has not been switched on, and the answers stay editable on the call afterwards \u2014 an installation that does go wrong is answered by a person. .6 because those fields record who REPORTED a fault and nobody reported this. .8 because an unknown cover gets asked about and a wrong one gets believed. .11 because the two writes are not one transaction: continuing would leave a call nothing points at, hidden among the successes, and the machine would be offered a second call.' },
  { id: 'FRS-084', urs: ['URS-072'], risk: 'Medium', title: 'Force Update Child Records',
    text: 'FRS-084.1 The cover registers shall clear every inheriting field on every machine under an entry when the operator requests it. FRS-084.2 The cover registers shall alter no field that the register does not declare as inheriting. FRS-084.3 The cover registers shall state the number of values that differ from the entry before clearing them. FRS-084.4 The cover registers shall state separately the number of values that repeat the entry. FRS-084.5 The cover registers shall name each field it is about to clear and the number of machines carrying it. FRS-084.6 The cover registers shall offer this action only while at least one value is pinned. FRS-084.7 The cover registers shall clear every machine under one entry in one statement. RATIONALE: .2 because the model, the serial and the machine\u2019s own supplied-with answers are the MACHINE\u2019S facts and clearing them would delete its identity. .3 and .4 are separate because the two are not the same act: clearing a value that repeats the entry changes nothing anybody can see, and clearing one that differs destroys a decision made about one machine, with no undo. .7 because a forty-machine sale would otherwise be forty round trips, any of which can fail half way and leave the entry half-inherited \u2014 the state this action exists to resolve.' },
  { id: 'FRS-083', urs: ['URS-071'], risk: 'Medium', title: 'Feedback Without a Report',
    text: '`feedback_without_report` (0229) lists every customer feedback with no visit reading \u201CSolved - Report Completed\u201D behind it, and names WHICH of four things is absent, because each needs a different fix: the feedback records no UCN; no call carries that UCN; the call has no visit at all; or the call has visits and none of them is the completed one. The last is the commonest, and the row carries `latest_visit_status` beside it so that \u201CSolved - Report Pending\u201D \u2014 the system stating a known absence \u2014 is distinguishable from \u201CUnsolved\u201D, which is a different problem. THE STATUS IS MATCHED ON ITS LETTERS AND DIGITS, not as a string: `is_report_completed()` reduces to lower-case alphanumerics, so a trailing space, a lower-case spelling and an en-dash all read as completed, and `isCompletedVisit()` in src/lib/reportMapping.ts is the client copy of the same rule. That is not defensive coding \u2014 the export this was written for carried \u201CSolved - Report Completed \u201D with a trailing space in all 378 rows, and a string comparison would have reported every one of those calls as missing its report. ANY visit reading completed is enough rather than the latest one: a call written up and then re-visited still has its report. A false entry here sends somebody to re-file a report that exists, which is wasted work and teaches them the list may mean nothing \u2014 the same argument as a `_status.sql` row that answers NO for nothing \u2014 so both rules are tested with the spellings that actually arrive. The view is `security_invoker`, so the ordinary call and feedback policies decide the rows; the SCREEN is restricted to administrators by `mod:/feedback-without-report`, at the user\u2019s direction (2026-09-22).' },
  { id: 'FRS-077', urs: ['URS-065'], risk: 'High', title: 'Bulk Report Mapping reads, resolves and only then writes',
    text: 'The screen runs in three stated steps and in this order: READ the sheet and work out which call each row belongs to; RESOLVE the superseded system’s file references into links; WRITE only the rows that came through both cleanly. Nothing is written until the operator has SEEN what each row resolved to, and rows that did not resolve are listed with the reason and are not written. The register it writes into is the visit history, whose records are never deleted, so a wrong write cannot be taken back — which is why the review is a step rather than a confirmation dialogue.' },
  { id: 'FRS-078', urs: ['URS-066'], risk: 'Medium', title: 'Pending Registrations is the queue, and every row leaves it by a stated route',
    text: 'Pending Registrations lists requests carrying no UC Number. Opening one offers exactly three outcomes — register it as a new call, map it to an existing call (its UCN is recorded against the request), or cancel it with a reason — and the request’s status records which. IT READS `call_requests`, NOT the sheet-era `pending_registrations` table: two corrections were aimed at the wrong table before that surfaced, and the distinction is recorded in the codebase notes as well as here.' },
  { id: 'FRS-079', urs: ['URS-067'], risk: 'High', title: 'The call edit rights are four sections, plus allotment and cancellation',
    text: '`calls.edit.complaint`, `calls.edit.customer`, `calls.edit.vigilance` and `calls.edit.contact` each gate one part of the record and are granted independently; `calls.allot` gates re-allocation to another engineer and `calls.cancel` gates cancelling and restoring a call. `calls.edit` remains the parent, so a role holding it holds the four sections — `parentAction()` resolves a section key to it — and a role may instead be given one section alone. `cover.edit` is the equivalent authority over the warranty and contract registers, and `admin.view` opens the administration pages READ-ONLY, so somebody may inspect configuration without the right to change users.' },
  // ---- Rev 2.4 (2026-09-13) ----------------------------------------------
  { id: 'FRS-076', urs: ['URS-064'], title: 'The migration runner refuses rather than let a credential reach a log', text: 'The database URL is passed to psql through the environment, never on a command line, and psql’s output is masked before it is logged. THAT WAS NOT SUFFICIENT, and a real run proved it twice. Node’s URL parser splits credentials at the LAST \u201C@\u201D and libpq at the FIRST, so a password containing an unencoded \u201C@\u201D makes libpq report a HOST built from a SUFFIX of the password — a string matching neither the password nor the URL, which no exact-value mask can catch. It reached a public build log while the platform’s own masking displayed the secret as masked throughout. scripts/apply-migrations.mjs now REFUSES before psql is invoked when the URL carries more than one \u201C@\u201D, names the correction and prints no part of the value: nothing can leak from a call that is not made. Every tail of the password of three characters or more is additionally masked, for any other tool reporting the same shape. The exposure already made is not undone by this and is recorded as requiring the credential to be rotated.', risk: 'High' },
  { id: 'FRS-075', urs: ['URS-063'], title: 'The read-only roles hold nothing that writes, and a copy is a one-time act', text: '0180 removes `review.edit` from the Zoho Migration role. It had arrived by copying: 0155 merged the Technical Support permission row into Zoho Migration on EVERY application of the RBAC bundle, so an authority granted deliberately on one role crossed to another silently. What it conferred was established against a database rather than read from the policy — `review.edit` grants ALL commands on `call_reviews`, and a user holding it answered a review, fired the trigger and raised a field failure report in their own name, a record the retention guard means can never be deleted. 0155 now SEEDS the role once and leaves it alone: two roles kept identical are one role with two names, and a separate role exists in order to diverge and be revoked without touching the other. The Technical Support grant is RETAINED, being the system owner’s decision. The status report tests only what the configuration bundle provides; the write authority each read-only role holds is reported by a diagnostic as a question for review, because a status row that reads NO on a deliberate grant sends somebody to re-apply configuration that cannot remove it.', risk: 'High' },
  { id: 'FRS-074', urs: ['URS-062', 'URS-040'], title: 'Every loadable register has a key its interface can infer', text: 'Ownership transfers are keyed on the hand-over document AND the machine (0184); recovered warranty entries on the model AND the serial (0185); customer feedback on the call (0186). Each is a GENERATED STORED column carrying a plain unique index, because the data interface can infer neither an expression index nor a partial one — `npm run check:upserts` verifies every declared target against a real database and refused a partial index written during this very revision. A row carrying no key is refused and named at the point of loading. Where a row has no key VALUE but must be retained — feedback naming no call — the key falls back to the row’s own identifier, so it is unique by construction and no record is deleted to permit an index. Existing duplicates are collapsed by the migration keeping the most recent, a second record of one thing being a correction of the first.', risk: 'Medium' },
  { id: 'FRS-073', urs: ['URS-061'], title: 'An ownership transfer is kept when the predecessor is unknown', text: '0072 completed a blank \u201Cfrom\u201D party from the machine master — correct while the master still names the PREVIOUS owner, and wrong once it has caught up, because the completion then returns the DESTINATION and the two are identical. The constraint refusing a transfer between one party and itself rejected the row, and one such row halted an entire file: 2,985 of 4,327 on the first real export, whose own \u201Cfrom\u201D column carries the same defect. 0182 and 0183 make the completion conditional and discard a supplied value equal to the destination; where the predecessor cannot be determined the field is left EMPTY and the hand-over is recorded with what is known. The constraint is retained and is now unreachable through the trigger: the invariant remains declared and nothing can write a row breaking it — what was wrong was manufacturing a value that violated it.', risk: 'High' },
  { id: 'FRS-072', urs: ['URS-060'], title: 'A device record is keyed on the model and the serial', text: 'Three registers were keyed on less than their identity, and each was corrected against MEASURED data rather than argument. The field failure register was keyed on the report number alone (0181): eight numbers in the 2016\u20132019 registers each cover several machines — one covers four — so 20 rows collapsed to 8 and TWELVE machines were lost on a load reporting success. Recovered warranty entries were keyed on the serial alone (0185): of 2,263 rows, 298 serials belong to more than one product — one serial is both an ANAVENT and an ORION, another is four machines — so 640 rows collapsed to 298 and THREE HUNDRED AND FORTY-TWO machines were lost. Ownership transfers carried no key at all (0184). Each key is now the pair, held as a GENERATED STORED column with a plain unique index. The rule was already stated in the codebase (src/lib/machine.ts) together with the incident that produced it — a request for one model’s serial 201 was offered an open call for another model’s serial 201, one action from being mapped onto it — and these three registers contradicted it.', risk: 'High' },
  // ---- Rev 2.1 (2026-09-11) ----------------------------------------------
  { id: 'FRS-061', urs: ['URS-053'], title: 'The serial is mandatory', text: 'The serial number is a required field on the call request and on the Field, Installation, PM and pending-registration call forms. The request refuses an item without one, and names the cause where the machine is absent from Product Database rather than inviting the field to be skipped. The request identifier is composed REQID-Product-Serial, so a missing serial is visible in the key itself.', risk: 'High' },
  { id: 'FRS-062', urs: ['URS-054'], title: 'Consumption is written as entered', text: 'The visit report writes every consumption line the engineer has entered, including the line still in the entry control at the moment of saving; the same validation applies to it as to a line already added. \u201CAdd Consumption?\u201D offers Yes or None Consumed: Yes requires at least one line before the report will save, and None Consumed withdraws the section. Lines are written in one statement, so a report cannot keep some of its spares and drop the rest.', risk: 'High' },
  { id: 'FRS-063', urs: ['URS-055'], title: 'Call Review register', text: 'A register (call_report_reviews, one row per call) records that a closed call’s report has been reviewed, with the reviewer taken from the authenticated session and a caller-supplied identity discarded. Writing requires the callreview.mark permission and visibility of the call; reading follows the call’s own visibility. The register lists solved calls only — a report-pending call has no report to review — filtered in the database.', risk: 'Medium' },
  { id: 'FRS-064', urs: ['URS-055'], title: 'Correction and re-opening from the review', text: 'From the review the reviewer may book a Reconciliation consumption line against the call, off the ATTENDING engineer’s hand stock and capped at what that engineer holds by the same database trigger as any other consumption; or re-open the call with a recorded reason, after which it leaves the review list. Consumption shown for a call is matched on the call number OR the unique call number, so a call predating the call-number series still shows its parts.', risk: 'Medium' },
  { id: 'FRS-071', urs: ['URS-037', 'URS-040'], title: 'The field failure register is loaded year by year, whatever shape each year is', text: 'The register exists on paper back to 2016, one spreadsheet TAB per year, and the years do not agree with one another. The Bulk Uploads definition maps each year’s headings onto `field_failure_reports` through the shared header matcher (case- and space-insensitive, several accepted names per column, one date parser), and ANY COLUMN IT DOES NOT RECOGNISE IS KEPT on the row in `extra` and named on screen as kept — so a format nobody anticipated loses nothing and the unfamiliar heading is something to name later rather than data discarded now. Rows are matched on the FFR NUMBER, which is unique, so a corrected year is re-loaded over itself and the years may be loaded in any order; a row with no number is refused, because without it the same row arrives again on every load. Two properties are enforced in the database rather than by the importer: every loaded row carries `imported_from`, so migrated years stay DISTINGUISHABLE from reports this system raised and any figure over the register can report the split (the Insights tab does); and `ffr_stamp` leaves `raised_by` NULL on a loaded row, because the sheet’s \u201CRaised by\u201D is a name with no user account behind it and stamping the person running the upload would attribute a 2016 report to somebody who never saw it. Loading old years cannot disturb the current year’s number, which is drawn per year.', risk: 'Medium' },
  { id: 'FRS-069', urs: ['URS-058'], title: 'The reviewer is stamped by the database at completion', text: 'A BEFORE trigger on `call_reviews` (0173) records `review2_by_uid` / `review3_by_uid` from auth.uid() at the moment a review stage becomes COMPLETE, and fills the display name from User Master where the client sent none — so the automatic-save and bulk-review paths, which send no name, record a person instead of nothing. A name the client did send is kept: it is what the reviewer saw on screen. A later edit does NOT re-stamp: the person who answered the review is the reviewer, not whoever last corrected a spelling. The trigger evaluates the completion test from the source columns rather than reading `review2_done`, because PostgreSQL computes a GENERATED column AFTER the BEFORE triggers have run — the first version read it, stamped nothing on every path, and was caught only by exercising it against a database. The duplicated expression is compared word-for-word with its original by an automated check. raise_ffr() carries the name onto the Field Failure Report, preferring Review 3’s reviewer, and no longer writes the string \u201CDaily Call Review\u201D — a screen is not a person, and a report that cannot name one is left blank, blank being a question somebody asks.', risk: 'High' },
  { id: 'FRS-070', urs: ['URS-059'], title: 'The report’s amendments are recorded by the database', text: '`ffr_history` (0174) receives one row per UPDATE of a field failure report, written by an AFTER trigger, holding `{column: {from, to}}` for only the columns that actually differ, with the person from auth.uid() and their User Master name. An update that changes nothing writes nothing, and `updated_at` is never an entry on its own — a log whose every line says the timestamp moved buries the one that says the CAPA was closed. It is written IN THE DATABASE rather than by the application because the application’s own audit trail is client-written (FRS-021) and therefore records only what a screen chose to report, seeing nothing of an amendment made directly through the API. The table has no insert, update or delete policy, so it cannot be forged, edited or tidied through the application, and 0166’s deletion guard is armed on it; reading it requires `ffr.manage` or administrator. Reports raised before it existed are given their creation entry, so every report’s history begins somewhere.', risk: 'High' },
  { id: 'FRS-066', urs: ['URS-057'], title: 'A signature is held for its owner only', text: 'A user records a signature on My Profile, drawn with a finger, stylus or mouse or uploaded as a picture of one on paper; it is stored as a transparent PNG cropped to the ink (0172_user_signatures.sql). It is held in its own table rather than on the profile, because Row-Level Security grants by ROW: a policy permitting a person to save a signature on their profile row would permit them to rewrite the role and permissions on it. The read and update policies test `user_id = auth.uid()` and NOTHING ELSE — no is_admin(), no users.manage — so no second party can obtain the image, and none can set one. The owning user id is stamped from the session by trigger, so a row naming another user is stored under the inserter.', risk: 'High' },
  { id: 'FRS-067', urs: ['URS-057'], title: 'A document signs only the block that names the printer', text: 'signatureBelongsTo() compares the name printed in the block with the identity of the signed-in user, on an EXACT match of name or e-mail ignoring case and surrounding space; a looser comparison would put one person’s signature on another’s document where names share a part. The Word copy of the Field Failure Report reproduces the CONTROLLED FORM itself — R-SER-03 Rev 02’s header band, two-column grid at the template’s own 6435/4500 split, every label with its exact wording and internal spacing, its A4 page setup and its footer carrying `TMPL No: R/SER/03 Rev: MAR 2020` — and a printable HTML page renders the SAME form from the same definition (src/lib/ffrform.ts), so a second transcription cannot drift from the first. The Delivery Challan reproduces the saved signature in the company block only when the person printing booked the stock out, and never in the customer’s block, which exists to be signed on receipt; the Field Failure Report (R-SER-03) embeds it only when the person generating the document is the raiser named on it. Where a signature is absent or unreadable the document is produced with an empty block, never with a broken image or a failure to produce it.', risk: 'High' },
  { id: 'FRS-068', urs: ['URS-057'], title: 'Administration of a signature discloses nothing', text: 'user_signature_status() reports, per user, WHETHER a signature has been saved and when — never the image. remove_user_signature() deletes one belonging to another person and is refused to a non-administrator and for the caller’s own row (which the Profile page removes). Both are SECURITY DEFINER functions, not views: a definer view over Row-Level-Security-protected tables reads as its owner and defeats the policies beneath it, which this system shipped three times, and the automated check that now refuses such a view is not weakened to admit these. A plain DELETE policy admitting an administrator was written first and does not work: PostgreSQL applies the SELECT policy to a DELETE that must locate its row, so an administrator unable to read the row reported a successful statement affecting nothing.', risk: 'Medium' },
  { id: 'FRS-065', urs: ['URS-056'], title: 'A role is created only by derivation', text: 'Roles may be added from Roles & Permissions by a holder of rbac.manage. The form requires a source role and copies its permissions; a role cannot be created with an empty set, because has_perm() treats an empty permission array as unconfigured and falls back to the engineer defaults — an \u201Cempty\u201D role would therefore grant an engineer’s authority. The key is derived as a slug from the name and cannot collide with an existing or reserved key. Roles are not deleted from this screen; a role in use is emptied or its users moved. Every role the database holds is drawn in the matrix and offered wherever a role is chosen.', risk: 'High' },
  { id: 'FRS-001', urs: ['URS-001'], title: 'Credential authentication', text: 'The system authenticates users against Supabase Auth (email + password); first sign-in forces a password set; sessions are token-based and expire.', risk: 'High' },
  { id: 'FRS-002', urs: ['URS-001'], title: 'Account lifecycle', text: 'Administrators create logins from User Master; a leaver’s login can be set inactive, blocking sign-in and hydration while retaining their historical records.', risk: 'High' },
  { id: 'FRS-003', urs: ['URS-002'], title: 'RBAC + reporting-tree scoping', text: 'Each role maps to a permission set (app_roles). Data visibility is scoped by a reporting tree resolved from User Master; enforced in the client and, authoritatively, by PostgreSQL Row-Level Security.', risk: 'High' },
  { id: 'FRS-004', urs: ['URS-002'], title: 'Server-side authorisation', text: 'Every read/write is governed by RLS policies keyed on the authenticated user (auth.uid()) and SECURITY DEFINER helper functions; the UI gate is secondary.', risk: 'High' },
  { id: 'FRS-005', urs: ['URS-003'], title: 'Call registration & UCN', text: 'Registering a request or a direct call inserts a call row; a database trigger assigns a unique UCN (date + type letter F/I/P + sequence) and a Call Number (request UniqueID or CLYY##### running series).', risk: 'High' },
  { id: 'FRS-006', urs: ['URS-003', 'URS-005', 'URS-006'], title: 'Call type segregation', text: 'Field, Installation and PM calls are stored in separate physical tables (field_calls / installation_calls / pm_calls) behind a compatibility view with routing triggers; a CHECK constraint prevents mis-filing.', risk: 'Medium' },
  { id: 'FRS-007', urs: ['URS-004'], title: 'Visit reporting & status', text: 'A report row is written per visit; a trigger recomputes the call’s status from the latest ENTRY (Unattended → Unsolved → Report pending → Solved). A “Solved - Report Completed” call becomes read-only to non-admins.', risk: 'High' },
  { id: 'FRS-008', urs: ['URS-006'], title: 'Installation gating', text: 'Insertion into installation_calls requires the install.create permission (Commercial, Hotline, admin); enforced by RLS.', risk: 'Medium' },
  { id: 'FRS-009', urs: ['URS-005'], title: 'PM bulk upload', text: 'An administrator uploads a CSV; rows are mapped, forced to PM type, previewed, then inserted in batches with UCN/Call Number assigned by the database.', risk: 'Medium' },
  { id: 'FRS-010', urs: ['URS-007'], title: 'Spare approval chain', text: 'A spare request creates per-part lines; each advances RM → Commercial → NSM → Stores. A per-stage database guard blocks a stage change unless the actor holds that stage’s permission.', risk: 'High' },
  { id: 'FRS-011', urs: ['URS-007'], title: 'Manager-scoped approval', text: 'A reporting manager sees and approves only their own team’s spare requests; their own request routes to their manager, not to themselves.', risk: 'High' },
  { id: 'FRS-012', urs: ['URS-008'], title: 'Dispatch & receipt', text: 'Stores dispatch generates a DC and stock-out; the engineer acknowledges receipt. Drop is available at any stage to Spare Coordinator / Hotline only.', risk: 'Medium' },
  { id: 'FRS-013', urs: ['URS-009'], title: 'Stock derivation & guard', text: 'Hand stock = stock-out − consumption − transfer-out + transfer-in − returned. A guard prevents a transfer/return exceeding holdings, counting every movement regardless of visibility.', risk: 'Medium' },
  { id: 'FRS-014', urs: ['URS-009', 'URS-002'], title: 'Stock visibility scope', text: 'Hand stock, transfers and returns are scoped to the reporting tree at the database, so a user sees only their own and their team’s stock.', risk: 'Medium' },
  { id: 'FRS-015', urs: ['URS-010'], title: 'Master maintenance', text: 'Party/Product/Part/User masters and value lists are editable by authorised roles; edits are gated by masters.edit, or per value list by master.<list>.edit / master.<list>.delete, and audit-logged where applicable. A value already in use is deactivated, not deleted.', risk: 'Medium' },
  { id: 'FRS-016', urs: ['URS-011'], title: 'Cover registers', text: 'Warranty (Sale Entry) and Contract (Contract Entry) registers hold the parent record; machines inherit its values unless individually pinned.', risk: 'Medium' },
  { id: 'FRS-017', urs: ['URS-012'], title: 'Feedback capture', text: 'Feedback answers are stored per question and surfaced as columns in the Customer Feedback view, scoped like calls.', risk: 'Low' },
  { id: 'FRS-018', urs: ['URS-013'], title: 'Reports & export gate', text: 'Visit history is retrievable with field filters; CSV export is blocked unless the user holds export.data.', risk: 'Medium' },
  { id: 'FRS-019', urs: ['URS-014'], title: 'SLA engine', text: 'Configurable SLA rules (hours + on/off) are evaluated per open call (first visit, closure, closure-with-spare, closure-spare-non-cover, stores dispatch); the Dashboard flags due/breached.', risk: 'Medium' },
  { id: 'FRS-020', urs: ['URS-015'], title: 'Notification triggers', text: 'Database triggers create a per-user notification when a call is allotted or a requested spare is dispatched; each user reads/marks only their own (RLS).', risk: 'Low' },
  { id: 'FRS-021', urs: ['URS-016'], title: 'Audit log', text: 'TWO TRAILS AGAIN, as of 0225 (2026-09-21). `audit_log` records what a USER DID — action, target, duration, outcome, actor and time — and its retention is configurable (app_settings.audit_retention_days, default ~10 years), with a daily digest built to archive the day off-database (supabase/functions/daily-digest) THAT HAS NEVER BEEN DEPLOYED — so no off-database archive exists today. Its LIMITS are stated rather than glossed: it is written by the CLIENT, so it can be bypassed by a direct API call, and it is purged when the retention window passes. THE SECOND TRAIL IS BACK ON. `record_audit` records what a ROW BECAME, before and after, in triggers that CANNOT BE BYPASSED and that nothing purges — stopped by 0112 on 2026-09-05 when it was thought to exist only for 21 CFR Part 11, and re-armed by 0225 at the user’s direction on 2026-09-21. The event that settled it was not a regulatory one: on 2026-09-20 a re-applied bundle set 4,222 calls back to Unattended, and NOTHING IN THE SYSTEM COULD SAY WHAT THEY HAD BEEN. A client-written trail cannot answer that, because the write did not come through the client. 0103’s shape is what was restored, not 0048’s: a BULK load is ONE attributable event rather than a row per record, so the trail stays about what people did. The table also still holds everything it captured 2026-08 to 2026-09-05; that gap, 05-Sep to 21-Sep, is real and is not recoverable.', risk: 'High' },
  { id: 'FRS-022', urs: ['URS-017'], title: 'Record integrity', text: 'Records are written to PostgreSQL with constraints; the publishable key is public by design and access is enforced by RLS; the service_role key is never shipped.', risk: 'High' },
  { id: 'FRS-023', urs: ['URS-018'], title: 'Backup/restore', text: 'The Supabase project provides managed backups; restore is periodically verified per procedure.', risk: 'Medium' },
  { id: 'FRS-024', urs: ['URS-019'], title: 'Release identity & change log', text: 'Each build carries a version, build number and build ID shown in the footer; an in-app Version History lists changes; source and schema changes are version-controlled.', risk: 'Medium' },
  { id: 'FRS-025', urs: ['URS-020'], title: 'Knowledge base', text: 'A how-to guide plus team field-solution articles (sanitised rich text) are available to all; author or admin edits.', risk: 'Low' },
  { id: 'FRS-026', urs: ['URS-021'], title: 'Partial dispatch', text: 'A stock out records a quantity per requested line in spare_dispatch_lines; spare_request_lines.dispatched_qty accumulates it. The Stores queue shows the outstanding remainder and the line stays queued until fully issued. Issuing more than the remainder is rejected by dispatch_spare_lines().', risk: 'Medium' },
  { id: 'FRS-027', urs: ['URS-022'], title: 'Per-shipment receipt', text: 'receive_spare_shipments() stamps each delivery with who confirmed it and when, accumulating spare_request_lines.received_qty. The line is marked Received (received_at) only when the acknowledged quantity reaches the requested quantity, so a part-delivered line remains at the Stores stage.', risk: 'Medium' },
  { id: 'FRS-028', urs: ['URS-023'], title: 'Reconciliation entry', text: 'Holders of consumption.reconcile (Spare Coordinator, Hotline, Admin) may insert consumption rows flagged source = Reconciliation. UCN (validated against an existing call), engineer, part and reason are mandatory and enforced by a database trigger; the entry records who made it. Parts offered are limited to the engineer’s hand stock.', risk: 'High' },
  { id: 'FRS-029', urs: ['URS-023'], title: 'Quantity adjustment and voiding', text: 'The same role may amend the quantity of an existing consumption line. The original quantity, the reason, and who amended it are retained on the row; the call, part, engineer and source cannot be altered. Setting the quantity to zero voids the line, returning the stock, while the record is retained (hard deletion remains blocked).', risk: 'High' },
  { id: 'FRS-030', urs: ['URS-024'], title: 'Consumption capped at hand stock', text: 'A database trigger rejects any consumption line, reported or reconciled, exceeding the engineer’s hand-stock balance for that part; an increase is checked on the delta. Rows naming no engineer or part are not checked, having no balance to check against.', risk: 'High' },
  { id: 'FRS-031', urs: ['URS-025'], title: 'Call re-open', text: 'An authorised role may re-open a closed call and close it again without inventing a visit; the transition is recorded.', risk: 'Medium' },
  { id: 'FRS-033', urs: ['URS-027'], title: 'Refurbished issue', text: 'Stores may mark a line as refurbished when issuing it. The issue records the recycled identity — R + part code, description unchanged — while the request keeps what was asked for. Hand stock is derived from the ISSUE, so the refurbished part is held and consumed under its own code. A database check refuses the swap unless that code exists in Part Master and is active, and the engineer’s dispatch notification states that the part is refurbished.', risk: 'High' },
  { id: 'FRS-035', urs: ['URS-029'], title: 'Service manual library & call lookup', text: 'Service manuals are catalogued in `documents` against the product they cover and stored in Google Drive. Opening a call lists its Supporting Documents — the manuals matching the call’s product, plus manuals held with no product (general to every machine) — alongside Knowledge Base articles whose title, product or tags match the call’s product or standard complaint. Every signed-in user may read the library; `docs.manage` maintains it.', risk: 'Medium' },
  { id: 'FRS-037', urs: ['URS-031'], title: 'Product & Party Search', text: 'A dedicated screen answers the question from either end. By product: the product list is the distinct set of item names in the PRODUCT REGISTER (view `product_register_names`, security_invoker) with the machine count beside each, and choosing one narrows Serial Number to that product’s serials — an equality match on `products.item_name`, served by the btree index of 0052, so a product name is never a prefix of another. By party: the party list opens the master and the box beside it takes any part of a name. Both land on one answer — the party, its recorded details, and every machine held against it. Export is deliberately absent from this screen.', risk: 'Low' },
  { id: 'FRS-038', urs: ['URS-032'], title: 'Bulk re-allotment', text: 'Every call register — Field, Installation, PM and Pending Calls — offers selection per row and a header box that takes exactly the rows currently listed, never rows a filter is hiding. The bar that appears edits ONE field, the allotted engineer, chosen from the manager and their reporting sub-tree, and writes every selected call in one action. The choice offered is built from `visible_engineer_names()`, and the write is independently constrained by RLS: a manager cannot allot outside their own team even by direct query.', risk: 'High' },
  { id: 'FRS-039', urs: ['URS-033'], title: 'Multi-level grouping', text: 'Any register built on the shared table component can be grouped by up to three columns at once (for calls: Region, Engineer, Call Status). Groups are formed from the rows the filters have already produced, nest in the order chosen, carry their own counts, and collapse independently; each user’s choice is remembered per screen against their own identity. Region is not held on a call — it is resolved from the allotted engineer’s User Master row.', risk: 'Low' },
  { id: 'FRS-040', urs: ['URS-034'], title: 'Raising on behalf of a team member', text: 'Where a manager may act for their team, the engineer is a field on the form rather than an assumption: the Spare Request, Call Registration Request and Reporting forms offer the manager and every engineer reporting to them, defaulting to the manager. The record carries the chosen engineer and their address, so it reaches that engineer’s own lists, while `created_by` retains the manager as its author. The list is the same reporting sub-tree the read policies use, so a manager cannot raise for somebody they cannot see.', risk: 'Medium' },
  { id: 'FRS-041', urs: ['URS-035'], title: 'Reassigning a spare order, with a log', text: '`reassign_spare_request()` changes the engineer on a spare request and writes `spare_request_engineer_log` in the same statement, so a change cannot exist without its record or a record without its change. It refuses a non-administrator, and refuses ANY caller once the order has been issued — tested three ways: the order says dispatched, any of its lines does, or a stock-out line points at one of its lines. A BEFORE UPDATE trigger on the table enforces the dispatch rule again for every path that does not go through the function, including PostgREST and the bulk upload. The reason: hand stock is DERIVED from the request, so after issue the engineer’s name is not a label on a record but the identity of whose parts they are. The log is readable by administrators, approvers, Stores, and both engineers named on the row.', risk: 'High' },
  { id: 'FRS-042', urs: ['URS-036'], title: 'KPI aggregates', text: 'Four database views (0101) compute the analysis: `spare_usage` joins each consumed part to its call for the cover and to the engineer’s User Master row for the region; `spare_usage_rollup` groups it by cover, region and product; `failure_rate_by_product` divides calls in the last 365 days by the machines of that product in the Product Register, giving calls per 100 machines; `failure_modes_by_product` groups calls by standard complaint. All four are security_invoker, so the figures a person reads are computed from exactly the records they may read. The install-base denominator is NOT scoped — it is a property of the fleet — so a user without full call visibility sees their own share of a whole-fleet denominator, and the screen states this rather than leaving it to be inferred. A product with no machines on record shows no rate at all instead of a rate divided by a guess.', risk: 'Medium' },
  { id: 'FRS-043', urs: ['URS-037'], title: 'The balance declares its migrated part', text: 'Hand stock is derived from nine arms, three of which are migrated: the opening pools (`ref_type = Opening balance`) and the pre-2026 stock outs and yearly consumption exports (`ref_type = Historical`). `handstock_balance` carries `hist_stock_out`, `hist_consumed`, `hist_net` and `on_hand_live` (0102), so the register shows what the migration contributes per line and can present the balance without it. The identity `on_hand - hist_net = on_hand_live` holds for every row. The whole line is restated when the migrated part is excluded, not only the total, so the components on screen still reconcile. Both figures are labelled; neither is offered as a correction of the other.', risk: 'High' },
  { id: 'FRS-044', urs: ['URS-038'], title: 'Period close', text: '`close_handstock_period(date)` writes an opening figure per engineer and part equal to the net of every movement up to that date, then moves a cut-off (`handstock_cutoff()`) that every arm of the movement view tests. The sum and the arms divide the SAME instant — the close takes `< cutoff`, the arms `>= cutoff` — so no movement can fall on both sides. Restricted to an administrator or `consumption.reconcile`; refuses a period that has not ended. A closing figure may be negative, because it must equal exactly what it replaces.', risk: 'High' },
  { id: 'FRS-045', urs: ['URS-039'], title: 'Identifier continuity', text: 'The call-request trigger assigns a REQID from a sequence when the row does not carry one, and when it DOES carry one advances the sequence past it (0097), so loading historical records cannot leave the counter beneath them. `resync_call_req_seq()` repairs a counter already stranded. Identifiers issued out of sequence before the repair are re-lettered rather than renumbered, so a record people have seen keeps its identity while ceasing to collide.', risk: 'High' },
  { id: 'FRS-046', urs: ['URS-040'], title: 'A batch is one shape', text: 'The API writes a batch of rows as ONE insert whose column list is the union of the rows’ keys; a row lacking one of those keys is written as NULL, not as the column default. The loader therefore groups rows by their column set and sends each group separately, so a column no row in the group carries genuinely defaults. Filling absent values in was rejected as a fix: it would defeat a default that carries meaning. A load that violates a NOT NULL constraint fails the batch and writes nothing of it.', risk: 'High' },
  { id: 'FRS-047', urs: ['URS-041'], title: 'Opening stock is an engineer’s', text: 'Both opening-stock registers resolve each row’s name against the ACTIVE user directory before writing, matching on `lower(btrim(name))` — the same normalisation the balance is keyed on. Rows that do not match are withheld and NAMED before anything is written, so the count approved is the count loaded. An empty directory is refused rather than treated as "nothing matches". `_handstock_opening_engineers.sql` applies the same rule to already-loaded data and reports what it removes.', risk: 'Medium' },
  { id: 'FRS-048', urs: ['URS-042'], title: 'Query response', text: 'Just-in-time compilation is disabled for the database (0099). The planner’s cost estimate for a view carrying row-level-security sub-plans exceeds `jit_above_cost` by several times, so Postgres compiled a query for 3.7 s that then executed in 174 ms — the more access rules a query carried, the more certain it was to be compiled. Registers page rather than requesting more rows than the API will return, and search is executed by the database rather than over the page already loaded.', risk: 'Medium' },
  { id: 'FRS-049', urs: ['URS-043'], title: 'Standard Complaint suggestion', text: 'Registering a call offers up to three Standard Complaints for the reported problem, each with its grounds. The first source is the REGISTER: `suggest_standard_complaint()` (0104) ranks by what was actually chosen on past calls whose reported problem resembles this one, matched two ways — whole-string similarity and word similarity, because "O2 sensor faulty" against "Oxygen sensor defective" scores 0.24 on the first and 0.41 on the second. A count of past decisions outranks a resemblance between strings. The second, optional, source is a model (Edge Function `suggest-complaint`) which RE-RANKS those same candidates and cannot return a value outside them, enforced on both sides of the call; it exists for the paraphrase the first source cannot reach. The field is written only by the person choosing, and `complaint_suggestions` records what was offered and what was taken. The function is SECURITY DEFINER so a new engineer is not given the worst suggestions, and returns aggregates only — a value, a count, a score — so no call a reader may not see crosses the boundary.', risk: 'Medium' },
  { id: 'FRS-050', urs: ['URS-002'], title: 'A view must not defeat the policies beneath it', text: 'Every view over a table carrying row-level security is created `security_invoker`, so the policies are evaluated for the READER. `create or replace view` does not carry the setting over, and a view running as its owner returns everything with no error and no warning. `npm run check:views` fails on any view over an RLS-protected table that lacks it, and `_status.sql` reports it on a live project; views intentionally readable by every signed-in user are enumerated with their reason.', risk: 'High' },
  { id: 'FRS-036', urs: ['URS-030'], title: 'QMS document control', text: 'QMS documents are held in the same catalogue under kind = qms with document number, revision and effective date, readable by every signed-in user and maintainable only under `qms.manage` — a right distinct from the one governing service manuals, and enforced in the database so a holder of either cannot move a document onto the other shelf. Withdrawal is by RETIRING the row (active = false): it stops being offered while the record of what was in force is retained. Authorship is stamped by the database and is not editable.', risk: 'High' },
  { id: 'FRS-034', urs: ['URS-028'], title: 'Days to dispatch', text: 'spare_stock_out_lines lists every spare issued, one row each, with days_to_dispatch measured from the last approval recorded on the line (NSM where the item needs that review, else Commercial, else RM) to the stock out.', risk: 'Low' },
  { id: 'FRS-051', urs: ['URS-044', 'URS-001'], title: 'Two names on a registration', text: 'Each call carries `created_by` — the Hotline DESK it is filed to, defaulting to the hotline-role profile or to an administrator’s configured choice (app_settings.calls.default_registrant_email) — and `actual_created_by`, the authenticated individual who registered it. A BEFORE INSERT trigger (0114, named so it fires last) sets the second from auth.uid() and DISCARDS any value the caller supplied; it accepts a supplied desk only when that user is a hotline desk, and otherwise substitutes the default. Where there is no authenticated session (a migration, a restore, an administrative load) both are kept as supplied and a missing one is filled from the other, so restored provenance is not erased. The two columns DIFFERING is the finding the control exists to produce, and the register lists and groups by the individual. Where neither can be determined — records bulk-loaded from the superseded system — both are empty and the record says so rather than implying attribution; `_registered_by_check.sql` reports where that line falls. Row-level security admits a reader on either column, so the individual who registered a call retains access to it.', risk: 'High' },
  { id: 'FRS-052', urs: ['URS-045'], title: 'One picking control, and typing never selects', text: 'Every dropdown in the application renders as a pick list that FILTERS on typing and commits only on a click or Enter over a highlighted row; a native `<select>` commits on the first keystroke, which on an auto-saving quality record wrote a value nobody chose. Below eight options the search box is suppressed, so a two-item list is not made harder to use. Free text is a per-field decision, OFF by default (`allowFreeText`); the form engine renders `type: select` this way, so every field-defined form inherits it. `npm run check:ui` fails the build on any native `<select>` remaining in the source.', risk: 'High' },
  { id: 'FRS-053', urs: ['URS-045'], title: 'Standard Complaint takes no free text anywhere', text: 'The Standard Complaint is a pick list with free text OFF on every screen that asks for it — the Field Call, Installation and PM registers (through the form engine), the Visit Report and the Call Registration request. Where the master is empty the control says whether it is empty or still loading and remains a picker. Suggestions drawn from past calls are offered beneath it and are values from the register itself, so they remain valid even when the master has not loaded.', risk: 'High' },
  { id: 'FRS-054', urs: ['URS-046'], title: 'Repeat-failure verdict computed in the database', text: '`frequent_failure(ucn)` returns the verdict and the calls behind it: earlier calls on the same product and serial within the window, matched on the same complaint OR the same part fitted, counted INCLUDING the call under review against the threshold. Window, threshold and whether the same-equipment path also requires a matching complaint are held in `app_settings` and editable in Admin Config; the defaults are the procedure’s (one month, two, on). The window is measured from the CALL’s date, not today, so reopening an old review cannot change its answer. A blank serial returns `known: false` — reported as \u201Ccannot tell\u201D rather than \u201Cno repeat failure\u201D. SECURITY DEFINER by design: an answer narrowed to the reader’s own call scope would read LOWER than the truth. Answers already recorded are not re-based; the screen shows the rule in force with the verdict.', risk: 'High' },
  { id: 'FRS-055', urs: ['URS-047'], title: 'Unaccounted spares are reportable', text: '`unused_spare_report` lists spare lines DISPATCHED or RECEIVED against a call whose part code is not fully accounted for in that call’s consumption — NOT USED where none was booked, SHORT where less was booked than sent. Quantities are aggregated per call and part, so a part sent twice and booked once is not two false findings. Refused and dropped lines are excluded: nothing arrived. Matched on the part CODE, the description being unstable. Only calls in a solved state are assessed, an open call’s parts being legitimately still in the van. `security_invoker`, so a reader sees only the calls their role allows.', risk: 'Medium' },
  { id: 'FRS-057', urs: ['URS-049'], title: 'The Indoor Service Register, on two axes', text: 'Equipment taken into the workshop is recorded in `indoor_jobs`, one row per intake, carrying `received_at` / `received_by`, `condition_on_arrival`, the physical `tag_no` and a `status` through nine states. TWO INDEPENDENT AXES: `kind` states whose property it is (Customer property | DEMO unit) and is what makes the custody duty applicable or not; `activity` states what is being done to it (Repair | Rework | Salvage | Pre-delivery inspection | Demo | Other). Neither is reachable from the other, so equipment does not change ownership because the work on it changed. `ucn` is NULLABLE — a demonstration unit has no call — which is why the register stands alone rather than being a state of a call. Damage is `damage_note` with `reported_to_customer_at` / `_by`. Accessories are rows in `indoor_job_accessories`, each tagged to the parent job, so what came in with the equipment is a list that can be checked off when it goes back.', risk: 'High' },
  { id: 'FRS-058', urs: ['URS-050'], title: 'Cleaning recorded against a revision, and a hard gate before dismantling', text: '`cleaned_at` / `cleaned_by` with `cleaning_wi` (defaulting to WI/SER/01) and `cleaning_wi_rev`, so the record states which revision was applied rather than which document was named. Where parts are recovered from equipment, a database trigger REFUSES the recovery while the job’s `decontaminated` flag is false: it is the only control in the module that blocks rather than records, because it protects the person doing the work and not only the product.', risk: 'High' },
  { id: 'FRS-059', urs: ['URS-051'], title: 'The check is its own record, and its own permission', text: '`qc_result` / `qc_by` / `qc_at` / `qc_notes` are columns of the job, not sentences in the work text. `indoor.qc` is a permission distinct from `indoor.work` and is enforced by a BEFORE UPDATE trigger, so a person holding every other authority in the module is refused the check by the database rather than by a hidden button. A trigger refuses any move to Ready, Dispatched or Closed while `qc_result` is Fail, refuses a Repair or Rework reaching Dispatched with no result at all, and refuses a failed pre-delivery inspection leaving. Whether the check must be signed by somebody OTHER than the person who received the unit is NOT enforced: the procedure does not require it, both identities are recorded, and the screen states plainly when they are the same.', risk: 'High' },
  { id: 'FRS-060', urs: ['URS-052'], title: 'Condemnation is gated, and recovered parts credit no balance', text: '`indoor.condemn` is a permission of its own, enforced by a trigger on insert and update, and granted to the administrator role alone when the schema is applied — so no role acquires the ability to scrap equipment merely by being given the page. `condemned_reason` is required by a CHECK constraint before the status may be Condemned, and `condemned_by` / `condemned_at` are stamped by the database. Recovered parts are rows in `indoor_job_parts` with a condition grade and a destination in words; NO stock balance is altered, because a recovered part entering stock under its ordinary code cannot afterwards be told from a new one.', risk: 'High' },
  { id: 'FRS-056', urs: ['URS-048'], title: 'Contract renewal carries the machines, not the prices', text: 'A contract raises its successor from the register: the machines (each removable before saving), contract type, party, period, PM visit count and billing schedule are carried; `prev_mc_number` on the header and `last_contract_number` / `last_contract_end` on each item record the link back. The successor starts the day AFTER the predecessor ends and a period ends the day BEFORE its anniversary, so `machine_cover` has one unambiguous answer per day. The MC number is entered, never generated, and is refused if it already exists — renewing into an existing number would merge two contracts. Rate, tax and total are left empty on every machine.', risk: 'Medium' },
  { id: 'FRS-080', urs: ['URS-068'], title: 'Product Database 2.0 assembles one row per machine from five registers', text: '`product_database_v2` (0218) lists every machine named by `warranty_sale_details`, `contract_details` or `product_additional_entries`, keyed by `machine_key(product, serial)` \u2014 the SQL twin of `machineKey()` in `src/lib/machine.ts`, squashed so ORION-G and ORION G are one model, and MODEL-plus-SERIAL so the eleven machines numbered 219 stay eleven rows. Ownership Transfer and the installation call are joined in. The party is the most recently DATED claim among the ownership transfer, the additional entry, the contract and the sale, ties breaking towards the transfer. `party_from`, `warranty_from`, `contract_from` and `item_status_reason` name the deciding register on every row. It does not replace `public.products` or `machine_cover`, both of which are left exactly as they are.', risk: 'High' },
  { id: 'FRS-081', urs: ['URS-069'], title: 'Item status is derived warranty-first, and a typeless contract is flagged', text: '`product_database_v2.item_status` is WGP where the warranty period covers today; otherwise `contract_cover_code(type)` where the contract period covers today \u2014 labour/labor to AMC, comprehensive/CMC to CMC, anything else returned UNCHANGED rather than bucketed; otherwise OGP. A contract covering today whose type is blank reads `CONTRACT (TYPE NOT RECORDED)`. This differs from `machine_cover` in both directions on purpose: that view asks the contract FIRST (so a machine inside warranty reads as its contract type) and defaults a blank type to CMC (so a labour contract silently reads as comprehensive).', risk: 'High' },
  { id: 'FRS-082', urs: ['URS-070'], title: 'Warranty start comes from the installation, and the end is computed like the app', text: 'Warranty start is the `Warranty Start Date?` answer on the installation call\u2019s feedback, read through `imported_ts()` so a cell holding "n/a" yields nothing rather than failing the whole view; failing that the installation call\u2019s solved date; failing that the additional entry; failing that the warranty sale. Where a start and a period are both known the end is `cover_period_end(start, months)`, which reproduces `addPeriod()` in `src/lib/dates.ts` INCLUDING its JavaScript month overflow \u2014 31 January plus one month is 2 March, where Postgres\u2019s own interval arithmetic clamps to 27 February. 26 of 458 start/period combinations differ between the two.', risk: 'High' },
  { id: 'FRS-032', urs: ['URS-026'], title: 'PM due-month batch', text: 'The PM bulk upload dates every call in a batch to the first of a chosen due month (reg_date), records the upload date as added_on, and sequences a registration date-and-time (reg_at) so the batch holds a stable order. Call numbering is unchanged.', risk: 'Medium' },
];

// ---- Non-Auditable Requirements --------------------------------------------
