// and are not offered as evidence against one. They are recorded here so the
// package accounts for everything the system does — a feature absent from the
// specification is the thing an assessor finds — while keeping the auditable
// requirements traceable to a clause. The classification is about PROVENANCE.
// It does not mean the requirement is untested, undocumented, or that its use
// goes unrecorded.
export interface NonAuditableReq extends Req { classification: string; rationale: string }
