// ---- Architecture (System) Design -----------------------------------------
export const ARCHITECTURE: { heading: string; body: string[] }[] = [
  { heading: 'Overview', body: [
    'A single-page web application (React 18 + TypeScript, built with Vite) served as static assets from GitHub Pages. It talks directly to a Supabase project (managed PostgreSQL + Auth + PostgREST API) over HTTPS.',
    'There is no custom application server: business rules and access control live in the database (RLS policies, SECURITY DEFINER functions, triggers, generated columns), so they are enforced regardless of client.',
  ] },
  { heading: 'Components', body: [
    'Client (browser): UI, local cache (offline-first, 30-min sync), role-aware rendering.',
    'Supabase Auth: identity, sessions (JWT), password management.',
    'PostgREST: REST access to tables/views, constrained by RLS.',
    'PostgreSQL: the system of record — tables, views, RLS, triggers, generated columns, pg_cron (audit retention, the review auto-answer, the Product Database 2.0 refresh). Two more jobs EXIST AS SCHEDULE FILES AND ARE NOT SCHEDULED — the daily digest and the scheduled export — because each pokes an Edge Function that has to be deployed first; see FRS-021 and NAR-004.',
    'Legacy Apps Script bridge (CallReg.gs): Drive file uploads and sheet-era reads when Supabase is not connected.',
  ] },
  { heading: 'Trust boundaries & security', body: [
    'The browser is untrusted; all authorisation is server-side via RLS keyed on auth.uid(). The anon/publishable key is public by design; the service_role key is never present in the client.',
    'Transport is TLS. Session tokens are short-lived. Server-side helper functions run SECURITY DEFINER with fixed search_path.',
  ] },
  { heading: 'Data flow (example: register a call)', body: [
    'User submits the request → PostgREST insert into the calls view → INSTEAD OF trigger routes to the typed table → BEFORE trigger assigns UCN & Call Number → RLS confirms the actor may create → row returned → client caches and displays.',
  ] },
  { heading: 'Deployment & configuration', body: [
    'Merges to the main branch trigger a GitHub Actions build (tsc + Vite) that publishes to gh-pages (the live site). Database schema is applied as numbered, idempotent migrations / consolidated apply-bundles run in the Supabase SQL editor.',
    'Configuration items under control: roles & permissions (app_roles + per-user extra), SLA rules, master value lists, and platform secrets (Edge Function).',
  ] },
];

// ---- Detailed Design -------------------------------------------------------
export const DETAILED: { area: string; points: string[] }[] = [
  { area: 'Identity & RBAC', points: [
    'profiles (role, active) + app_roles (role → permissions jsonb) + per-user extra_permissions. has_perm() resolves effective permissions with an engineer-default fallback when a role list is empty.',
    'visible_engineer_names() resolves the reporting sub-tree via a recursive CTE over user_directory; can_view_all_calls() grants office/admin/data.view_all holders full visibility.',
  ] },
  { area: 'Calls & state', points: [
    'calls split into field_calls / installation_calls / pm_calls with a UNION view + INSTEAD OF routing triggers and per-table CHECK. Generated column open_state derives status; sync_call_last_visit() maintains last visit from reports (latest entry by updated_at).',
    'pending_calls / call_state views expose open calls and status; next_ucn() and next_direct_call_number() assign identifiers.',
  ] },
  { area: 'Spare workflow', points: [
    'spare_requests (header) + spare_request_lines (per part). spare_line_stage() computes the stage; spare_requests_stage_guard() enforces per-stage permission on write; spare_pending_dispatch view lists Stores-stage lines awaiting a DC.',
    'RLS scopes requests to creator / engineer email / reporting tree / approvers.',
  ] },
  { area: 'Stock', points: [
    'handstock_movements / handstock_balance (security_invoker) derive stock from dispatch, consumption, transfers and MRN returns; a stock guard blocks overdraw counting all movements.',
  ] },
  { area: 'Audit & data integrity', points: [
    'The trail is `audit_log`: user actions with actor, target, duration and outcome, DB-stamped identity and time, admin/audit.view read-only and not user-editable. The database-enforced trail (record_audit) runs alongside it again from 2026-09-21 (0225), having been stopped on 2026-09-05 (0112). It takes a before/after image of every row on the ten quality tables, in triggers no API call can bypass and no retention purge touches — which is what answers “what was this record before?” when the change did not come through the application. Both the reduction and its reversal are recorded here rather than left implied, and so is what neither can undo: nothing was captured between 05-Sep and 21-Sep-2026.',
    'A BULK WRITE IS RECORDED AS ONE EVENT, not one row per record (0103): who, which table, how many rows, when. An audit trail answers "who changed this record and to what"; a data load is not that question, and is verified instead by the migration checks (DM1..DM10). The load stays attributable, which is what record control asks of it; what is not kept is a per-record duplicate of data already in the table it was loaded into. The line is drawn by a statement-level trigger counting the rows one statement touched — and the bulk USER actions reach the typed tables one row at a time through the calls view’s INSTEAD OF triggers, so they are audited in full regardless of the threshold.',
    'Retention is configurable (app_settings.audit_retention_days, default ~10 years) — the earlier 7-day purge is replaced. NO OFF-DATABASE ARCHIVE EXISTS, AND THE REASON GIVEN FOR THAT ON 2026-09-22 WAS WRONG. Earlier revisions stated that a daily email digest archived the day’s trail. That was withdrawn on the ground that the system had no mail path at all — and it has one: supabase/functions/daily-digest sends through Resend, attaches the day’s record_audit as a CSV and ships with a pg_net schedule, and this package’s supplier appendix already named Resend. The correct statement is the narrower one: THAT FUNCTION HAS NEVER BEEN DEPLOYED, no digest has ever been sent, and the only pg_cron jobs running are the retention purge, the review auto-answer and the Product Database 2.0 refresh. So the archive does not exist, and it is one deployment away rather than a thing that must be designed. NAR-004 is the scheduled export beside it, built to the same shape and awaiting the same deployment.',
    'Application deletion of quality records is blocked (record-retention guard); only a controlled DBA/superuser action can remove them, and that too is audited. Records are constrained (unique UCN, FKs) in PostgreSQL.',
  ] },
  { area: 'SLA & notifications', points: [
    'sla_rules (hours + active) evaluated by evaluateCallSla() to on-track/due/breach. notifications created by SECURITY DEFINER triggers on allotment and dispatch; RLS scopes to recipient.',
  ] },
  { area: 'Spare issue, receipt and stock control', points: [
    'A stock out is a header (spare_dispatches) plus one row per issued line (spare_dispatch_lines), because a requested line may be issued across several stock outs; the delivery challan prints what that stock out carried, not the line’s full request.',
    'spare_request_lines carries dispatched_qty and received_qty. The Stores queue exposes the outstanding remainder as its quantity, so every consumer counts what is still due. The line leaves the queue only when fully issued, and is marked Received only when fully acknowledged.',
    'Hand stock is derived, never stored: stock issued, less consumption, plus/minus transfers, less returns. Consumption is therefore the control point, and a before-insert trigger caps every consumption line at the engineer’s balance for that part.',
    'Hand stock is derived from what was ISSUED, not what was requested, so a spare sent as a recycled part (R + code, same description) is held and consumed under that code and never merges with new stock. A legacy arm keeps any line marked Dispatched without issue rows in the ledger, so the derivation change moves no existing stock.',
    'Reconciliation rows are ordinary consumption rows flagged source = Reconciliation, so they move stock identically while remaining distinguishable in the register and in reports. Amendments retain the original quantity, the reason and the author ON THE ROW — which is now the whole of it: record_audit no longer takes an independent before/after image (0112), so the retained fields are the record.',
  ] },
  { area: 'Reading a register: scope, grouping and bulk edit', points: [
    'The shared table component owns selection, filtering and grouping, so every register inherits them identically. A header tick takes the ROWS CURRENTLY LISTED and nothing else — what a filter is hiding cannot be selected by accident. Grouping nests up to three columns, forms groups from the already-filtered rows, and remembers each user’s choice per screen keyed on their own identity, so one person’s view never becomes another’s.',
    'The engineer chips on the calls and spare registers are the same control as the spare stage chips: a value list with its count, drawn from the rows on screen.',
    'Bulk re-allotment edits one field. The names offered come from `visible_engineer_names()` — the recursive reporting sub-tree — and the write is constrained again by RLS, so the list is a convenience and the boundary is the database.',
    'Region is NOT a column on a call. `useRegionByEngineer()` resolves it from the allotted engineer’s User Master row, which is why a call allotted to nobody groups under “no region” rather than under a guess.',
  ] },
  { area: 'Product & Party Search', points: [
    'One screen, asked from either end, landing on one answer: the party, its details and every machine held against it.',
    'The product list is the register’s own — `product_register_names`, a security_invoker view giving the distinct `item_name` and its machine count — not the hand-kept master value list, which had been short. Choosing a product narrows Serial Number to that product’s serials and makes the search an EQUALITY match, so “MONNAL T75” cannot return “MONNAL T75 NF”. Equality is served by the btree index of 0052; a trigram index does not serve it.',
    'The screen has no export, deliberately: it answers a question at the desk, and a customer’s installed base is not a file to be carried away.',
  ] },
  { area: 'Acting for a team member', points: [
    'Where a manager may act for their team, the engineer is an explicit field defaulting to the manager, offering the manager plus their reporting sub-tree. The record carries the chosen engineer and their address so it reaches that engineer’s lists; `created_by` retains the manager, so attribution and ownership stay distinct.',
    'Correcting the engineer on a spare order is a separate, narrower right: `reassign_spare_request()` (administrators, before issue) writes the change and `spare_request_engineer_log` together. A BEFORE UPDATE trigger refuses an engineer change on an issued order by ANY path — the function, PostgREST, a script, the bulk upload. Hand stock is derived from the request, so after issue the name is not a label but whose parts they are; moving it then would move stock between balances with nothing to show for it. A stock transfer is the correct instrument at that point, and it leaves a movement.',
  ] },
  { area: 'Migrated data, and telling it apart', points: [
    'Three of the nine arms of `handstock_movements` are the superseded system’s record, loaded once: the opening pools (`ref_type = Opening balance`), the pre-2026 stock outs and the yearly consumption exports (both `Historical`). They are held in their own tables and never merged into the current ones, so the distinction survives.',
    '`handstock_balance` therefore reports both readings and the split between them, and `on_hand - hist_net = on_hand_live` is an identity of the view, not an assertion of the client. One function restates a line without the migrated part, so the table, the filter chips, the summary tiles and the search results cannot disagree about what "without history" means.',
    'A PERIOD CLOSE fixes an opening figure and moves a cut-off that every arm tests. The close and the arms divide the same instant from opposite sides (`< cutoff`, `>= cutoff`), which is what makes a close provably neutral; an earlier cut that used the closed DATE against `>` counted the closing day on both sides and moved the balance.',
  ] },
  { area: 'Bulk loading', points: [
    'The API renders a batch as ONE insert over the union of the rows’ keys, so a row missing a key is written as NULL rather than taking the column default. Rows are grouped by column set and each group sent separately; a column absent from every row of a group defaults as intended. Filling the gaps with empty values was tried and rejected — it defeats defaults that carry meaning, which the loader’s own checks caught.',
    'Names in a migrated file are resolved against the ACTIVE user directory before writing, on the same normalisation the target is keyed by, and what is withheld is named before the write is approved. An empty directory is refused rather than read as "nothing matches".',
    'Row references are derived so that re-loading a file corrects rather than duplicates; where a reference proved insufficient the reference was widened rather than the duplicate tolerated.',
  ] },
  { area: 'Response time', points: [
    'JIT compilation is off for the database. The planner’s estimate for a view carrying RLS sub-plans is several times `jit_above_cost`, so the query was compiled for 3.7 s and executed in 174 ms — and the more access rules a query carried, the more certain that became. Switching RLS off appeared to fix it, which is why the cause took three attempts to find; the JIT block of an execution plan is the first thing to read when a query is slow and its execution time is not.',
    'Registers page rather than asking for more rows than the API returns — a request for 5,000 was answered with 1,000 and nothing said so. Search is executed by the database, because filtering the page already loaded cannot find what has not been loaded.',
  ] },
  { area: 'Client integrity controls', points: [
    'HTML authored in the Knowledge Base editor is sanitised (allowlist) before storage and render. CSV export is centrally gated. The offline cache is per-table with sync markers and a Force-update that clears caches.',
  ] },
];

